EffectBank.Effect:
float TAU = acos(-1.0) * 2.0;

float rnd(float x) {
	return fract(sin(x*32949.0) + sin(x*432.9));
}

void main() {
	vec3 col = vec3(0);
	vec3 p = (iPixelPos3D - pixelPosMin) / (pixelPosMax-pixelPosMin);
	p -= 0.5;
	float a = atan(p.z, p.x);
	float l = length(p.xz);
	for (int i=0; i<4; i+=1) {
		float h1 = rnd(float(i+461)), h2=rnd(h1);
		float trail_len = 0.1 + h1 * 0.8;
		float speed = (i%2==0?-1:1) * (h1+0.1) * 2.0; /* change 2.0 here to change speed*/
		float angle = speed * time + (a - h2 * TAU);
		col += 0.0
			+ smoothstep(trail_len, 0.0, sin(angle)*0.5+0.5)
			* smoothstep(0.1, 0.0, abs(p.y-sin(angle*2.0)*0.4))
			//* smoothstep(0.2, 0.0, abs(l-0.25)) /* not disk */
			* (vec3(h1,h2,rnd(h2))+0.2)
		;
	}

	col = max(vec3(0), col);
	//col += length(col) < 1e-3 ? vec3(0.3,0,0) : vec3(0);
    fragColor = vec4(col, 1.0);
}

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p) {
    vec2 i = floor(p); vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i+vec2(1,0)), u.x),
               mix(hash(i+vec2(0,1)), hash(i+vec2(1,1)), u.x), u.y);
}
void main() {
    vec2 q = iPixelPos2D;
    q.y = 1.0 - q.y;  // flame rises upward
    float t = time * 1.5;
    float f = noise(q * vec2(10.0, 5.0) + vec2(0.0, -t));
    f += 0.5 * noise(q * vec2(10.0, 10.0) + vec2(0.0, -t * 1.3));
    f = clamp(f - q.y * 1.1, 0.0, 1.0);
    vec3 fire = mix(vec3(1.0, 0.0, 0.0), vec3(1.0, 0.9, 0.0), f);
    fire = mix(vec3(0.0), fire, pow(f, 0.4));
    fragColor = vec4(fire, 1.0);
}

float TAU = acos(-1.0) * 2.0;

float rnd(float x) {
	return fract(sin(x*32949.0) + sin(x*432.9));
}

void main() {
	vec3 col = vec3(0);
	vec3 p = (iPixelPos3D - pixelPosMin) / (pixelPosMax-pixelPosMin);
	p -= 0.5;
	float a = atan(p.z, p.x);
	for (int i=0; i<5; i+=1) {
		float h1 = rnd(float(i)), h2=rnd(h1);
		float trail_len = h1 * 0.8;
		float angle = sign(h1-0.5) * 2.0 * time + (a - h2 * TAU);
		col += 0.0
			+ smoothstep(trail_len, 0.0, sin(angle)*0.5+0.5)
			* smoothstep(0.1, 0.0, abs(p.y-sin(angle*2.0)*0.4))
		;
	}

	col = max(vec3(0), col);
	//col += length(col) < 1e-3 ? vec3(0.3,0,0) : vec3(0);
    fragColor = vec4(col, 1.0);
}

// Protean clouds by nimitz (twitter: @stormoid)
// https://www.shadertoy.com/view/3l23Rh
// License Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License

mat2 rot(in float a){float c = cos(a), s = sin(a);return mat2(c,s,-s,c);}
const mat3 m3 = mat3(0.33338, 0.56034, -0.71817, -0.87887, 0.32651, -0.15323, 0.15162, 0.69596, 0.61339)*1.93;

float mag2(vec2 p){return dot(p,p);}
float linstep(in float mn, in float mx, in float x){ return clamp((x - mn)/(mx - mn), 0., 1.); }

float prm1 = 0.;
vec2 bsMo = vec2(0.0);

vec2 disp(float t){ return vec2(sin(t*0.22)*1., cos(t*0.175)*1.)*2.; }

vec2 map(vec3 p)
{
    vec3 p2 = p;
    p2.xy -= disp(p.z).xy;
    p.xy *= rot(sin(p.z+time)*(0.1 + prm1*0.05) + time*0.09);
    float cl = mag2(p2.xy);
    float d = 0.;
    p *= .61;
    float z = 1.;
    float trk = 1.;
    float dspAmp = 0.1 + prm1*0.2;
    for(int i = 0; i < 5; i++)
    {
        p += sin(p.zxy*0.75*trk + time*trk*.8)*dspAmp;
        d -= abs(dot(cos(p), sin(p.yzx))*z);
        z *= 0.57;
        trk *= 1.4;
        p = p*m3;
    }
    d = abs(d + prm1*3.)+ prm1*.3 - 2.5 + bsMo.y;
    return vec2(d + cl*.2 + 0.25, cl);
}

vec4 render( in vec3 ro, in vec3 rd, float t_val )
{
    vec4 rez = vec4(0);
    const float ldst = 8.;
    vec3 lpos = vec3(disp(t_val + ldst)*0.5, t_val + ldst);
    float t = 1.5;
    float fogT = 0.;
    for(int i=0; i<130; i++)
    {
        if(rez.a > 0.99)break;

        vec3 pos = ro + t*rd;
        vec2 mpv = map(pos);
        float den = clamp(mpv.x-0.3,0.,1.)*1.12;
        float dn = clamp((mpv.x + 2.),0.,3.);

        vec4 col = vec4(0);
        if (mpv.x > 0.6)
        {
            col = vec4(sin(vec3(5.,0.4,0.2) + mpv.y*0.1 +sin(pos.z*0.4)*0.5 + 1.8)*0.5 + 0.5,0.08);
            col *= den*den*den;
            col.rgb *= linstep(4.,-2.5, mpv.x)*2.3;
            float dif =  clamp((den - map(pos+.8).x)/9., 0.001, 1. );
            dif += clamp((den - map(pos+.35).x)/2.5, 0.001, 1. );
            col.xyz *= den*(vec3(0.005,.045,.075) + 1.5*vec3(0.033,0.07,0.03)*dif);
        }

        float fogC = exp(t*0.2 - 2.2);
        col.rgba += vec4(0.06,0.11,0.11, 0.1)*clamp(fogC-fogT, 0., 1.);
        fogT = fogC;
        rez = rez + col*(1. - rez.a);
        t += clamp(0.5 - dn*dn*.05, 0.09, 0.3);
    }
    return clamp(rez, 0.0, 1.0);
}

float getsat(vec3 c)
{
    float mi = min(min(c.x, c.y), c.z);
    float ma = max(max(c.x, c.y), c.z);
    return (ma - mi)/(ma+ 1e-7);
}

vec3 iLerp(in vec3 a, in vec3 b, in float x)
{
    vec3 ic = mix(a, b, x) + vec3(1e-6,0.,0.);
    float sd = abs(getsat(ic) - mix(getsat(a), getsat(b), x));
    vec3 dir = normalize(vec3(2.*ic.x - ic.y - ic.z, 2.*ic.y - ic.x - ic.z, 2.*ic.z - ic.y - ic.x));
    float lgt = dot(vec3(1.0), ic);
    float ff = dot(dir, normalize(ic));
    ic += 1.5*dir*sd*ff*lgt;
    return clamp(ic,0.,1.);
}

void main() 
{   
    // Using your 'iPixelPos2D' input instead of calculating from gl_FragCoord
    vec2 q = iPixelPos2D;
    vec2 p = (iPixelPos2D - 0.5) * (resolution.xy / resolution.y);

    // Fallback for iMouse
    bsMo = vec2(0.0);

    float t_val = time*3.;
    vec3 ro = vec3(0,0,t_val);

    ro += vec3(sin(time)*0.5,sin(time*1.)*0.,0);

    float dspAmp = .85;
    ro.xy += disp(ro.z)*dspAmp;
    float tgtDst = 3.5;

    vec3 target = normalize(ro - vec3(disp(t_val + tgtDst)*dspAmp, t_val + tgtDst));
    ro.x -= bsMo.x*2.;
    vec3 rightdir = normalize(cross(target, vec3(0,1,0)));
    vec3 updir = normalize(cross(rightdir, target));
    rightdir = normalize(cross(updir, target));
    vec3 rd=normalize((p.x*rightdir + p.y*updir)*1. - target);
    rd.xy *= rot(-disp(t_val + 3.5).x*0.2 + bsMo.x);
    prm1 = smoothstep(-0.4, 0.4,sin(time*0.3));

    vec4 scn = render(ro, rd, t_val);

    vec3 col = scn.rgb;
    col = iLerp(col.bgr, col.rgb, clamp(1.-prm1,0.05,1.));

    col = pow(col, vec3(.55,0.65,0.6))*vec3(1.,.97,.9);

    // Vignette
    col *= pow( 16.0*q.x*q.y*(1.0-q.x)*(1.0-q.y), 0.12)*0.7+0.3; 

    fragColor = vec4( col, 1.0 );
}

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
void main() {
    vec2 cell = floor(iPixelPos2D * 20.0);
    float rnd  = hash(cell + floor(time * 12.0));
    float spark = step(0.94, rnd);
    fragColor = vec4(vec3(spark), 1.0);
}

float maxComp(vec3 p) {
	return max(max(p.x, p.y), p.z);
}

void main() {
	vec3 p = (iPixelPos3D - pixelPosMin) / maxComp(pixelPosMax-pixelPosMin) - 0.5;
    float dist = length(p);
    float radius = mix(0.1, 0.45, 0.5 + 0.5 * sin(time * 1.5));
    float intensity = smoothstep(0.1, 0.0, dist-radius);//smoothstep(radius + 15.0, radius - 15.0, dist);
    vec3 color = vec3(0.5 + 0.5 * sin(time),
                      0.5 + 0.5 * sin(time + 2.09),
                      0.5 + 0.5 * sin(time + 4.18));
    fragColor = vec4(color * intensity, 1.0);
}

void main() {
    vec3 dir = normalize(vec3(1.0, 0.4, 0.7));
    float proj = dot(iPixelPos3D, dir);

    float spatialFreq = 0.01;
    float speed = 6.0;
    float wave = sin(proj * spatialFreq - time * speed) * 0.5 + 0.5;

    vec3 col = vec3(0.5 + 0.5 * sin(proj * 0.003 + time),
                    0.5 + 0.5 * sin(proj * 0.003 + time + 2.09),
                    0.5 + 0.5 * sin(proj * 0.003 + time + 4.18));
    fragColor = vec4(col * wave, 1.0);
}

//@velocity_range 0.05 0.35

vec3 mod289(vec3 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec4 mod289(vec4 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec4 permute(vec4 x) {
     return mod289(((x*34.0)+10.0)*x);
}

vec4 taylorInvSqrt(vec4 r)
{
  return 1.79284291400159 - 0.85373472095314 * r;
}

float snoise(vec3 v)
  { 
  const vec2  C = vec2(1.0/6.0, 1.0/3.0) ;
  const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);

// First corner
  vec3 i  = floor(v + dot(v, C.yyy) );
  vec3 x0 =   v - i + dot(i, C.xxx) ;

// Other corners
  vec3 g = step(x0.yzx, x0.xyz);
  vec3 l = 1.0 - g;
  vec3 i1 = min( g.xyz, l.zxy );
  vec3 i2 = max( g.xyz, l.zxy );

  //   x0 = x0 - 0.0 + 0.0 * C.xxx;
  //   x1 = x0 - i1  + 1.0 * C.xxx;
  //   x2 = x0 - i2  + 2.0 * C.xxx;
  //   x3 = x0 - 1.0 + 3.0 * C.xxx;
  vec3 x1 = x0 - i1 + C.xxx;
  vec3 x2 = x0 - i2 + C.yyy; // 2.0*C.x = 1/3 = C.y
  vec3 x3 = x0 - D.yyy;      // -1.0+3.0*C.x = -0.5 = -D.y

// Permutations
  i = mod289(i); 
  vec4 p = permute( permute( permute( 
             i.z + vec4(0.0, i1.z, i2.z, 1.0 ))
           + i.y + vec4(0.0, i1.y, i2.y, 1.0 )) 
           + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));

// Gradients: 7x7 points over a square, mapped onto an octahedron.
// The ring size 17*17 = 289 is close to a multiple of 49 (49*6 = 294)
  float n_ = 0.142857142857; // 1.0/7.0
  vec3  ns = n_ * D.wyz - D.xzx;

  vec4 j = p - 49.0 * floor(p * ns.z * ns.z);  //  mod(p,7*7)

  vec4 x_ = floor(j * ns.z);
  vec4 y_ = floor(j - 7.0 * x_ );    // mod(j,N)

  vec4 x = x_ *ns.x + ns.yyyy;
  vec4 y = y_ *ns.x + ns.yyyy;
  vec4 h = 1.0 - abs(x) - abs(y);

  vec4 b0 = vec4( x.xy, y.xy );
  vec4 b1 = vec4( x.zw, y.zw );

  //vec4 s0 = vec4(lessThan(b0,0.0))*2.0 - 1.0;
  //vec4 s1 = vec4(lessThan(b1,0.0))*2.0 - 1.0;
  vec4 s0 = floor(b0)*2.0 + 1.0;
  vec4 s1 = floor(b1)*2.0 + 1.0;
  vec4 sh = -step(h, vec4(0.0));

  vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
  vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;

  vec3 p0 = vec3(a0.xy,h.x);
  vec3 p1 = vec3(a0.zw,h.y);
  vec3 p2 = vec3(a1.xy,h.z);
  vec3 p3 = vec3(a1.zw,h.w);

//Normalise gradients
  vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
  p0 *= norm.x;
  p1 *= norm.y;
  p2 *= norm.z;
  p3 *= norm.w;

// Mix final noise value
  vec4 m = max(0.5 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
  m = m * m;
  return 105.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1), 
                                dot(p2,x2), dot(p3,x3) ) );
  }

float TAU = acos(-1.0) * 2.0;

float rnd(float x) {
	return fract(sin(x*32949.0) + sin(x*432.9));
}

float n(float x) {
	return mix(rnd(floor(x)), rnd(floor(x+1.0)), fract(x));
}

float grey(vec3 rgb) {
	return dot(vec3(0.7, 0.3, 0.8), rgb);
}

vec3 pal(float d) {
	vec3 col = samplePalette(fract(d)).rgb;
	return col;
}

void main() {
	vec3 col = vec3(0);
	vec3 p = (iPixelPos3D - pixelPosMin) / (pixelPosMax-pixelPosMin);
	p -= 0.5;
	p -= distortion * snoise(p);
	float t = vTime * 0.5; /* change motion speed here */
	vec3 dir = normalize(vec3(n(t), n(t+0.329), n(t+1.334))-0.5);
	vec3 dir2 = normalize(vec3(n(t), n(t+1.329), n(t+2.334))-0.5);
	p = mix(p, abs(p)- dir2*asymmetry, asymmetry);
	float grad = dot(p, dir) / dot(dir,dir);
	grad *= scale + 0.1;
	grad *= (7. + n(t) * 8.0);
	grad -= vTime * 5.0 - intensity * pow(sin(vTime * 25.0)*0.5+0.5,1.0);
	t = time * 1.0; /* change color speed here */
	col += pal(grad);
	col = vec3(0,0,cos(time*1.0)*.5+0.5);
    fragColor = vec4(col, 1.0);
}

float TAU = acos(-1.0) * 2.0;

float rnd(float x) {
	return fract(sin(x*32949.0) + sin(x*432.9));
}

float n(float x) {
	return mix(rnd(floor(x)), rnd(floor(x+1.0)), fract(x));
}

vec3 star(vec3 p) {
	float s = 1.0 + scale * 10.0;
	vec3 gv = fract(p * s) - 0.5;
	vec3 id = floor(p * s);
	vec3 off = vec3(n(id.x), n(id.y), n(id.y)) - 0.5;
	off *= 0.4;
	float d = length(gv - off)-0.4;
	return vec3(smoothstep(0.01, 0.0, d));
}

void main() {
	vec3 col = vec3(0);
	vec3 p = (iPixelPos3D - pixelPosMin) / (pixelPosMax-pixelPosMin);
	p -= 0.5;

	float t = vTime * 1.0; /* change motion speed here */
	vec3 dir = mix(normalize(vec3(0, sin(vTime*2.0) + cos(vTime), cos(vTime)) + vec3(0, sin(vTime), 0)), normalize(vec3(n(t), n(t+0.329), n(t+1.334))-0.5), complexity);

	t = vTime * 0.2; /* change color speed here */
	float grad = dot(p, dir) / dot(dir,dir);
	grad *= scale * 10.0 + 1.0;
	grad = min(grad, 0.0);
	col += 0
		+ grad + 0.8
		* (samplePalette(fract(t)).rgb)
	;
	//col = vec3(star(p));
	//col = max(vec3(0), col);
    fragColor = vec4(col, 1.0);
}

